"""Reference compiler: direct transcription of the specification."""
import sys
from fractions import Fraction
sys.path.insert(0,'/workspace/tmp')
import brute

def trunc(a,l):
    return (a >> (128-l) << (128-l)) if l < 128 else a

def canon(a):
    g=[(a>>(16*(7-i)))&0xffff for i in range(8)]
    best=-1; bl=0; i=0
    while i<8:
        if g[i]==0:
            j=i
            while j<8 and g[j]==0: j+=1
            if j-i>=2 and j-i>bl: best=i; bl=j-i
            i=j
        else: i+=1
    if best<0: return ':'.join('%x'%x for x in g)
    return ':'.join('%x'%x for x in g[:best])+'::'+':'.join('%x'%x for x in g[best+bl:])

def build_image(entries, cuts):
    S=len(cuts)-1
    stages=[]
    for i in range(S):
        b=cuts[i]; e=cuts[i+1]
        if i==0:
            nodes=[0]
        else:
            nodes=sorted({trunc(a,b) for (a,l,h) in entries if l>b})
        objs=[]
        for x in nodes:
            rules=[]; edges=set()
            for (a,l,h) in entries:
                if trunc(a,b)!=x: continue
                if b<l<=e: rules.append((l,a,h))
                elif b==0 and x==0 and l==0: rules.append((l,a,h))
                if l>e: edges.add(trunc(a,e))
            rules.sort(key=lambda t:(t[0],t[1]))
            edge_list=sorted(edges)
            child_index={}
            if i+1<S:
                nb=cuts[i+1]
                nxt=sorted({trunc(a,nb) for (a,l,h) in entries if l>nb})
                child_index={a:j for j,a in enumerate(nxt)}
            objs.append({
                'prefix': canon(x)+'/'+str(b),
                'rules': [{'prefix': canon(a)+'/'+str(l), 'hop':h} for (l,a,h) in rules],
                'edges': ([{'prefix': canon(a)+'/'+str(e), 'child': child_index[a]} for a in edge_list]
                          if e<128 else []),
            })
        stages.append({'nodes':objs})
    used=[brute.stage_usage(entries,cuts[i],cuts[i+1]) for i in range(S)]
    return stages, used

def all_cut_vectors(S, max_stride):
    res=[]
    def rec(prefix):
        if len(prefix)==S+1:
            res.append(list(prefix)); return
        lo=prefix[-1]+1
        hi=min(128, prefix[-1]+max_stride)
        if len(prefix)==S:
            hi=128
            if lo>128: return
        for v in range(lo,hi+1):
            rec(prefix+[v])
    rec([0])
    return res

def compile_ref(entries, caps, max_stride):
    S=len(caps)
    best=None
    for cuts in all_cut_vectors(S, max_stride):
        used=[brute.stage_usage(entries,cuts[i],cuts[i+1]) for i in range(S)]
        if any(used[i]>caps[i] for i in range(S)):
            continue
        peak=Fraction(0)
        for i in range(S):
            peak=max(peak,Fraction(used[i],caps[i]))
        if best is None or peak<best[0]:
            best=(peak, cuts, used)
    if best is None:
        return None
    stages, used2 = build_image(entries, best[1])
    assert used2==best[2]
    return {'status':'ok','capacities':list(caps),'max_stride':max_stride,
            'cuts':best[1],'stages':stages,'used_bits':best[2],
            'peak':{'num':best[0].numerator,'den':best[0].denominator}}
